#if UNITY_EDITOR
using System.Linq; using UnityEditor; using UnityEngine;
namespace UnityCli { public class PhysicsJointRemoveTool : IUnityCliTool<PhysicsJointRemoveTool.Request, PhysicsJointResult> { public sealed class Request { [UnityCliRequired] public string Target { get; set; } public string Type { get; set; } public int? ComponentIndex { get; set; } } public ToolDescriptor Describe() => new() { Name = "physics.joint.remove", Summary = "Remove Joint components from a scene GameObject.", Description = "Removes all matching Joint components from target, or one selected by componentIndex. This changes scene memory only, supports dryRun=true, and is available in Edit and Play mode.", Group = "physics", Version = "1.0.0", SupportsDryRun = true, SideEffects = new[] { "scene-modify" }, Target = "editor", PlayModeSupport = "supported", DefaultTimeoutMs = 30000, MaxTimeoutMs = 600000, Examples = new[] { new ToolExample { Description = "Preview fixed joint removal", Input = new Request { Target = "Player", Type = "FixedJoint", ComponentIndex = 0 }, Execution = new ToolExampleExecution { DryRun = true } }, new ToolExample { Description = "Remove fixed joint", Input = new Request { Target = "Player", Type = "FixedJoint", ComponentIndex = 0 } } } }; public System.Threading.Tasks.ValueTask<PhysicsJointResult> ExecuteAsync(Request request, UnityCliProjectToolContext ctx, System.Threading.CancellationToken ct = default) { var (target, type) = PhysicsJointToolSupport.Resolve(request.Target, request.Type, "physics.joint.remove"); var joints = target.GetComponents(type).Cast<Joint>().ToArray(); if (joints.Length == 0) throw new UnityCliBridge.BridgeCommandException("E_PHYSICS_JOINT_NOT_FOUND", "No matching Joint component found on target: " + type.Name, "Check target and type, or add one with physics.joint.add."); var index = request.ComponentIndex ?? -1; if (index >= joints.Length) throw new UnityCliBridge.BridgeCommandException("E_PHYSICS_JOINT_INDEX_INVALID", "componentIndex is outside the matching Joint component range.", "Pass a componentIndex from 0 to " + (joints.Length - 1) + "."); var removed = index >= 0 ? 1 : joints.Length; if (!ctx.DryRun) { if (index >= 0) UnityCliSceneMutation.DestroyObject(joints[index]); else foreach (var joint in joints) UnityCliSceneMutation.DestroyObject(joint); UnityCliSceneMutation.MarkSceneDirty(target.scene); } return new(new PhysicsJointResult { DryRun = ctx.DryRun, Target = PhysicsJointToolSupport.TargetRef(target), Type = type.Name, Removed = removed, PlannedEffects = PhysicsJointToolSupport.Effects("physics.joint.remove", "remove", type.Name) }); } } }
#endif
